// PLC-Ki German texts (review 49). I18N.add({ "English text": "Deutsch" }) is read by PK.t(); I18N.addRules([...]) by PK.srv().
// The English text is the key and must match the PK.t("...") literal exactly; tests/PlcKi.Tests/LanguageTests.cs checks that every
// PK.t literal in js/*.js has an entry here. Keep the {name} and "singular|plural" parts the same as the English.
//
// Glossary (plant-floor German as on HMIs, Sie-form, short labels, infinitive on buttons):
//   alarm Alarm/Alarme · fault Störung · warning Warnung · acknowledge quittieren · active alarm Aktiver Alarm
//   plant (page) Anlage · machine Maschine · line Linie · station Station · device Gerät · shift Schicht · handover Übergabe
//   cycle Zyklus · cycle time Taktzeit · step Schritt · sequence / step chain Ablauf / Schrittkette · program Programm · block Baustein
//   network Netzwerk · interlock Verriegelung · tag Variable · value Wert · setpoint Sollwert · actual value Istwert
//   input Eingang · output Ausgang · memory Merker/Speicher · data block Datenbaustein · history Verlauf · recording Aufzeichnung
//   report Bericht · setup Einrichtung · settings Einstellungen · connection Verbindung · PLC SPS · diagnostics Diagnose
//   running Läuft · stopped Gestoppt · waiting Wartet · down Gestört · save Speichern · cancel Abbrechen · delete Löschen
//   close Schließen · done Fertig · log in/out Anmelden/Abmelden · note Notiz · cause Ursache · fix Abhilfe
//   downtime Stillstand · availability Verfügbarkeit · performance Leistung · quality Qualität · good parts Gutteile · scrap Ausschuss
//   Dates and numbers follow PK.fmt: German pages use 03.11.2026, 24 h and the decimal comma until a format is chosen.

