  "A machine setting stops it from working|{n} machine settings stop it from working": "Eine Maschineneinstellung verhindert den Betrieb|{n} Maschineneinstellungen verhindern den Betrieb",
  "{label} is {value}: {problem}.": "{label} ist {value}: {problem}.",
