  "The mode switch on the CPU is at {sw}.": "Der Betriebsartenschalter an der CPU steht auf {sw}.",
  "Someone set it there: find out why before it goes back to RUN.": "Jemand hat ihn dort eingestellt: Klären Sie, warum, bevor er wieder auf RUN geht.",
  "Look at the mode switch on the CPU: RUN or STOP.": "Prüfen Sie den Betriebsartenschalter an der CPU: RUN oder STOP.",
  "Open the CPU's diagnostic buffer in TIA Portal (Online & diagnostics). The newest entry says why it stopped.": "Öffnen Sie den Diagnosepuffer der CPU im TIA Portal (Online & Diagnose). Der neueste Eintrag nennt den Grund für den Stopp.",
  "Ask who stopped it: a download or a STOP from TIA or the CPU display, or a fault in the program (cycle time, a missing block, an access error).": "Fragen Sie, wer sie gestoppt hat: ein Download oder ein STOP aus TIA oder am CPU-Display, oder ein Fehler im Programm (Zykluszeit, ein fehlender Baustein, ein Zugriffsfehler).",
  "Start it again only when you know why it stopped and the machine is safe to run.": "Starten Sie sie erst wieder, wenn Sie wissen, warum sie gestoppt hat und die Maschine sicher laufen kann.",
  "What the CPU reports": "Meldungen der CPU",
  "No message from the CPU right now. Its diagnostic buffer in TIA says why it stopped.": "Gerade keine Meldung von der CPU. Ihr Diagnosepuffer in TIA nennt den Grund für den Stopp.",
  "PLC in {word}": "SPS in {word}",
