  "As they were when the CPU stopped. Fix the STOP first; some may go when the program runs again.": "So, wie sie beim Stopp der CPU waren. Beheben Sie zuerst den STOP; einige verschwinden, wenn das Programm wieder läuft.",
  "No alarm · {n} device blocked|No alarm · {n} devices blocked": "Kein Alarm · {n} Gerät blockiert|Kein Alarm · {n} Geräte blockiert",
