  "Every tag of the PLC tag tables with its address, and every value of the data blocks, read live from the PLC.": "Jede Variable der SPS-Variablentabellen mit ihrer Adresse und jeder Wert der Datenbausteine, live aus der SPS gelesen.",
  "Change a value with the pen: on PLCSIM (safety values after a warning), on a real PLC only memory and data values, when allowed and confirmed.": "Einen Wert ändern Sie mit dem Stift: auf PLCSIM (Sicherheitswerte nach einer Warnung), auf einer echten SPS nur Merker- und Datenwerte, wenn erlaubt und bestätigt.",
  "Change a value with the pen on PLCSIM (safety values after a warning).": "Einen Wert ändern Sie mit dem Stift auf PLCSIM (Sicherheitswerte nach einer Warnung).",
  "PLC-Ki runs on test values, so tags outside the machine model show no value.": "PLC-Ki läuft mit Testwerten, daher zeigen Variablen außerhalb des Maschinenmodells keinen Wert.",
  "PLC-Ki is not reading the PLC right now, so there are no live values.": "PLC-Ki liest die SPS gerade nicht, daher gibt es keine Livewerte.",
