  "None yet.": "Noch keine.",
  "Built in": "Eingebaut",
  "{n} entries of general knowledge: Siemens CPU, PROFINET, module, safety and SINAMICS drive messages, FANUC robot alarms and IO-Link events. Your own manuals come first when both know a code.": "{n} Einträge allgemeinen Wissens: Siemens-CPU-, PROFINET-, Baugruppen-, Sicherheits- und SINAMICS-Antriebsmeldungen, FANUC-Roboteralarme und IO-Link-Ereignisse. Ihre eigenen Handbücher haben Vorrang, wenn beide einen Code kennen.",
  "Copy files in instead": "Stattdessen Dateien hineinkopieren",
  "PLC-Ki also reads files you copy into these folders on this PC. Press Look for new files after copying.": "PLC-Ki liest auch Dateien, die Sie in diese Ordner auf diesem PC kopieren. Klicken Sie nach dem Kopieren auf „Nach neuen Dateien suchen“.",
