  "Try fewer words or a longer time window.": "Versuchen Sie weniger Wörter oder einen längeren Zeitraum.",
  "Alarms are recorded from the moment PLC-Ki watches the machine.": "Alarme werden ab dem Moment aufgezeichnet, in dem PLC-Ki die Maschine beobachtet.",
  "Change this value in the PLC": "Diesen Wert in der SPS ändern",
  "I understand": "Verstanden",
  "Understood": "Verstanden",
  "Hold on PLCSIM is not possible for an output: the program rewrites outputs every cycle, and PLCSIM only keeps inputs.": "Halten auf PLCSIM ist bei einem Ausgang nicht möglich: Das Programm schreibt Ausgänge in jedem Zyklus neu, und PLCSIM behält nur Eingänge.",
  "Change a value": "Wert ändern",
  "So PLC-Ki uses the rules for a real PLC.": "Daher wendet PLC-Ki die Regeln für eine echte SPS an.",
  "milliseconds, or 5s, 2m, T#1M30S": "Millisekunden oder 5s, 2m, T#1M30S",
  "a number, e.g. 12.5": "eine Zahl, z. B. 12,5",
  "text": "Text",
  "a whole number": "eine ganze Zahl",
  "Real PLC · change a value": "Echte SPS · Wert ändern",
  "This changes the running machine.": "Dies ändert die laufende Maschine.",
  "Make sure nobody is in the machine and that the change is safe. It is logged with your name and reason. Inputs, outputs and values the safety program reads are never changed.": "Stellen Sie sicher, dass sich niemand in der Maschine befindet und die Änderung sicher ist. Sie wird mit Ihrem Namen und Grund protokolliert. Eingänge, Ausgänge und Werte, die das Sicherheitsprogramm liest, werden nie geändert.",
  "A one-time change of an input is overwritten at the next cycle: the CPU reads its inputs at the start of every cycle.": "Eine einmalige Änderung eines Eingangs wird im nächsten Zyklus überschrieben: Die CPU liest ihre Eingänge zu Beginn jedes Zyklus.",
  "To keep a value, hold the simulated input instead.": "Um einen Wert zu behalten, halten Sie stattdessen den simulierten Eingang.",
  "Hold on PLCSIM": "Auf PLCSIM halten",
  "New value": "Neuer Wert",
  "Why": "Grund",
  "needed on a real PLC, goes into the change log": "bei einer echten SPS erforderlich, kommt ins Änderungsprotokoll",
  "optional": "optional",
  "e.g. test valve XV101 after repair": "z. B. Ventil XV101 nach der Reparatur testen",
  "e.g. test the door alarm": "z. B. Türalarm testen",
  "Type {plc} to confirm": "Zur Bestätigung {plc} eingeben",
  "Write to the real PLC": "In die echte SPS schreiben",
  "Write": "Schreiben",
  "An S7-1500 can force only inputs and outputs, so to change this for good, change the program, or on PLCSIM change what feeds it.": "Eine S7-1500 kann nur Eingänge und Ausgänge forcen. Um dies dauerhaft zu ändern, ändern Sie daher das Programm oder auf PLCSIM das, was den Wert speist.",
  "An S7-1500 can force only inputs and outputs, so to change this for good, change the program.": "Eine S7-1500 kann nur Eingänge und Ausgänge forcen. Um dies dauerhaft zu ändern, ändern Sie daher das Programm.",
  "Writing…": "Schreibt…",
  "changed": "geändert",
  "The PLC holds the new value (read back: {after}).": "Die SPS hält den neuen Wert (zurückgelesen: {after}).",
  "The PLC holds the new value.": "Die SPS hält den neuen Wert.",
  "The value did not stay.": "Der Wert ist nicht geblieben.",
  "Put back {value}": "{value} wiederherstellen",
  "Held at {value} by {user}, {time}. Release puts back {before}.": "Gehalten bei {value} von {user}, {time}. Beim Freigeben wird {before} wiederhergestellt.",
  "This sets the simulated input in PLCSIM. It stays until you release it; release puts back {value}. It is not a CPU force: TIA's force table does not show it.": "Dies setzt den simulierten Eingang in PLCSIM. Er bleibt, bis Sie ihn freigeben; beim Freigeben wird {value} wiederhergestellt. Es ist kein CPU-Force: Die Forcetabelle von TIA zeigt es nicht an.",
  "Value to hold": "Zu haltender Wert",
  "optional, goes into the change log": "optional, kommt ins Änderungsprotokoll",
  "Hold": "Halten",
  "On PLCSIM a fault switch of the machine simulator (its data block) is often the better way to test this.": "Auf PLCSIM ist ein Störschalter des Maschinensimulators (sein Datenbaustein) oft der bessere Weg, dies zu testen.",
  "Holding…": "Hält…",
  "held": "gehalten",
  "PLCSIM holds {address} at {value} until you release it. The strip at the top of every page shows it.": "PLCSIM hält {address} bei {value}, bis Sie es freigeben. Die Leiste oben auf jeder Seite zeigt es an.",
  "PLCSIM reads {now}, not {value}. Something else sets this input.": "PLCSIM liest {now}, nicht {value}. Etwas anderes setzt diesen Eingang.",
  "Release now": "Jetzt freigeben",
  "{symbol} held at {value} on PLCSIM": "{symbol} auf PLCSIM bei {value} gehalten",
  "{symbol} released: back to {now}.": "{symbol} freigegeben: zurück auf {now}.",
  "Inputs held on PLCSIM ({n})": "Auf PLCSIM gehaltene Eingänge ({n})",
  "Each stays until released; release puts back the value it had before.": "Jeder bleibt, bis er freigegeben wird; beim Freigeben wird der vorherige Wert wiederhergestellt.",
  "PLCSIM could not be read just now ({error}), so this is PLC-Ki's own list.": "PLCSIM konnte gerade nicht gelesen werden ({error}), daher ist dies die eigene Liste von PLC-Ki.",
  "Input": "Eingang",
  "Held at": "Gehalten bei",
  "Before": "Vorher",
  "Who": "Von",
  "Since": "Seit",
  "Held": "Gehalten",
  "Released": "Freigegeben",
