  "{places} sets this when its condition is true, so a change may not stay.|{places} set this when their conditions are true, so a change may not stay.": "{places} setzt dies, wenn die Bedingung wahr ist, daher bleibt eine Änderung möglicherweise nicht erhalten.|{places} setzen dies, wenn ihre Bedingungen wahr sind, daher bleibt eine Änderung möglicherweise nicht erhalten.",
