  "{n} different alarm in this time. History ranks them by how long they were on, with what fixed them.|{n} different alarms in this time. History ranks them by how long they were on, with what fixed them.": "{n} verschiedener Alarm in diesem Zeitraum. Der Verlauf ordnet sie nach der Dauer, die sie aktiv waren, mit der jeweiligen Abhilfe.|{n} verschiedene Alarme in diesem Zeitraum. Der Verlauf ordnet sie nach der Dauer, die sie aktiv waren, mit der jeweiligen Abhilfe.",
