  "An end before the start runs past midnight. Planned stops (breaks, cleaning) are not counted as lost time.": "Ein Ende vor dem Start läuft über Mitternacht. Geplante Stopps (Pausen, Reinigung) zählen nicht als verlorene Zeit.",
  "Planned stops, min": "Geplante Stopps, min",
  "Add a shift": "Schicht hinzufügen",
  "Parts and cycles": "Teile und Zyklen",
  "Good part counter": "Gutteilzähler",
  "A tag that goes up by one per part. Without one, every finished cycle counts as one part.": "Eine Variable, die pro Teil um eins steigt. Ohne sie zählt jeder abgeschlossene Zyklus als ein Teil.",
  "★ looks like a counter.": "★ sieht wie ein Zähler aus.",
  "Reject counter": "Ausschusszähler",
  "Without one, quality counts as 100 % and the report says so.": "Ohne ihn zählt die Qualität als 100 % und der Bericht weist darauf hin.",
  "Cycle sequence": "Zyklus-Ablauf",
  "One cycle is finished when this sequence comes back to its first step.": "Ein Zyklus ist abgeschlossen, wenn dieser Ablauf zu seinem ersten Schritt zurückkehrt.",
  "Ideal cycle time, seconds": "Ideale Taktzeit, Sekunden",
  "Empty: the fastest cycles PLC-Ki has seen": "Leer: die schnellsten Zyklen, die PLC-Ki gesehen hat",
  "The fastest the machine can make one part, for Performance.": "Die kürzeste Zeit, in der die Maschine ein Teil fertigen kann, für die Leistung.",
  "How PLC-Ki counts": "So zählt PLC-Ki",
  "a sequence is past its first step and no fault alarm is on. With no sequences in the model, a device switched on.": "ein Ablauf ist über seinen ersten Schritt hinaus und kein Störungsalarm ist aktiv. Ohne Abläufe im Modell: ein Gerät ist eingeschaltet.",
  "a fault alarm is on. The reason is the alarm that came first.": "ein Störungsalarm ist aktiv. Grund ist der Alarm, der zuerst kam.",
  "no fault, but the sequence waits in its first step or is halted.": "keine Störung, aber der Ablauf wartet in seinem ersten Schritt oder ist angehalten.",
  "{a} and {b} (PLC-Ki was off) are left out of OEE.": "{a} und {b} (PLC-Ki war aus) werden in der OEE nicht berücksichtigt.",
  "Availability (running ÷ planned time) × Performance (ideal cycle × parts ÷ running time) × Quality (good ÷ all parts).": "Verfügbarkeit (Laufzeit ÷ geplante Zeit) × Leistung (idealer Zyklus × Teile ÷ Laufzeit) × Qualität (Gutteile ÷ alle Teile).",
  "Recorded in {folder}, one small file per day.": "Aufgezeichnet in {folder}, eine kleine Datei pro Tag.",
  "Saved. The reports use these settings from now on.": "Gespeichert. Die Berichte verwenden ab jetzt diese Einstellungen.",
  "Shift report with OEE, and a summary for maintenance. Made from what PLC-Ki records while it watches the machine. Past alarms are in History.": "Schichtbericht mit OEE und eine Zusammenfassung für die Instandhaltung. Erstellt aus dem, was PLC-Ki beim Beobachten der Maschine aufzeichnet. Frühere Alarme stehen im Verlauf.",
