  "Print a label for each station (and, if you like, each device) and stick it on the machine. Scanning it with a phone opens that station's live status and alarms.": "Drucken Sie ein Etikett für jede Station (und, wenn gewünscht, jedes Gerät) und kleben Sie es an die Maschine. Beim Scannen mit dem Smartphone öffnen sich der Livestatus und die Alarme dieser Station.",
