  "PLC-Ki, TIA Portal, and the cable to the PLC.": "PLC-Ki, TIA Portal und das Kabel zur SPS.",
  "Start PLC-Ki (double-click Start-PLC-Ki). That is all.": "PLC-Ki starten (Doppelklick auf Start-PLC-Ki). Das ist alles.",
  "PLC-Ki starts the TIA helper by itself when you import a program or build blocks.": "PLC-Ki startet den TIA-Helfer selbst, wenn Sie ein Programm importieren oder Bausteine erzeugen.",
  "Your PC": "Ihr PC",
  "PLC-Ki. It reads the PLC directly.": "PLC-Ki. Es liest die SPS direkt.",
  "The VM": "Die VM",
  "TIA Portal and the TIA helper.": "TIA Portal und der TIA-Helfer.",
  "Start PLC-Ki on the PC (double-click Start-PLC-Ki).": "PLC-Ki auf dem PC starten (Doppelklick auf Start-PLC-Ki).",
  "Live values, alarms and Ask work with the VM off.": "Livewerte, Alarme und Fragen funktionieren bei ausgeschalteter VM.",
  "The VM is only needed to import a program or for the block generator. After a one-time setup, the TIA helper starts by itself when you log into the VM.": "Die VM wird nur zum Importieren eines Programms oder für den Baustein-Generator gebraucht. Nach einer einmaligen Einrichtung startet der TIA-Helfer selbst, wenn Sie sich an der VM anmelden.",
  "The server": "Der Server",
  "PLC-Ki, open from any browser.": "PLC-Ki, aus jedem Browser erreichbar.",
  "Your laptop": "Ihr Laptop",
  "PLC-Ki Link and TIA Portal. It reaches the PLC.": "PLC-Ki Link und TIA Portal. Er erreicht die SPS.",
  "PLC-Ki runs on the server by itself.": "PLC-Ki läuft von selbst auf dem Server.",
  "On the laptop, start PLC-Ki Link. It reads the PLC and sends the values to the server, and does the TIA work.": "Starten Sie auf dem Laptop PLC-Ki Link. Es liest die SPS, sendet die Werte an den Server und erledigt die TIA-Arbeit.",
  "Checking…": "Prüft…",
  "Which setup is yours?": "Welche Einrichtung ist Ihre?",
  "PLC-Ki needs the PLC for live values, and TIA Portal only to import a program or build blocks. Pick the one that looks like yours. You can change it later.": "PLC-Ki braucht die SPS für Livewerte und TIA Portal nur zum Importieren eines Programms oder Erzeugen von Bausteinen. Wählen Sie die Variante, die Ihrer ähnelt. Sie können sie später ändern.",
  "What runs where": "Was wo läuft",
  "Every day": "Jeden Tag",
  "Tip: installed with {link} (the installer), PLC-Ki runs by itself in the background and starts with Windows, so there is no window to keep open.": "Tipp: Wurde mit {link} (dem Installationsprogramm) installiert, läuft PLC-Ki selbst im Hintergrund und startet mit Windows, sodass kein Fenster offen bleiben muss.",
  "PLC-Ki runs as a Windows service on this PC, so it cannot open the TIA helper window itself.": "PLC-Ki läuft auf diesem PC als Windows-Dienst und kann daher das Fenster des TIA-Helfers nicht selbst öffnen.",
  "Set the helper up as for a VM (double-click Setup-TIA-helper on this PC) and choose {preset} with the address {address}.": "Richten Sie den Helfer wie bei einer VM ein (Doppelklick auf Setup-TIA-helper auf diesem PC) und wählen Sie {preset} mit der Adresse {address}.",
  "PC with a TIA VM": "PC mit TIA-VM",
  "<the key>": "<der Schlüssel>",
  "PLC-Ki Link on your laptop": "PLC-Ki Link auf Ihrem Laptop",
  "The laptop reads the PLC and sends the values here. It only connects out to this server, so the plant network needs no changes.": "Der Laptop liest die SPS und sendet die Werte hierher. Er verbindet sich nur nach außen zu diesem Server, das Anlagennetz braucht keine Änderungen.",
  "Make a key.": "Schlüssel erzeugen.",
  "It lets your laptop in. It is shown once.": "Er lässt Ihren Laptop herein. Er wird nur einmal angezeigt.",
  "Make a new key": "Neuen Schlüssel erstellen",
  "Make a key": "Schlüssel erstellen",
  "Key made. It is in the command below.": "Schlüssel erzeugt. Er steht im Befehl unten.",
  "A key exists. Make a new one if you lost it.": "Ein Schlüssel existiert. Erzeugen Sie einen neuen, falls Sie ihn verloren haben.",
  "On the laptop, open Command Prompt and paste this one line.": "Öffnen Sie auf dem Laptop die Eingabeaufforderung und fügen Sie diese eine Zeile ein.",
  "Leave the window open.": "Lassen Sie das Fenster offen.",
  "Wait here.": "Hier warten.",
  "This turns green within a few seconds:": "Das wird innerhalb weniger Sekunden grün:",
  "Link connected from {name}": "Link verbunden von {name}",
  "the laptop": "dem Laptop",
  "reading the PLC": "liest die SPS",
