  "The TIA helper answers on {name}.": "Der TIA-Helfer antwortet auf {name}.",
  "PLCSIM downloads go to {ip}.": "PLCSIM-Downloads gehen an {ip}.",
  "The PLC answers at {address}. Continue to save it.": "Die SPS antwortet unter {address}. Weiter, um sie zu speichern.",
  "Make a new key?": "Neuen Schlüssel erstellen?",
  "Link on the laptop stops working until it is started with the new key.": "Link auf dem Laptop funktioniert nicht mehr, bis es mit dem neuen Schlüssel gestartet wird.",
  "alarm": "Alarm",
