  "Notes, documents, logins, settings and keys are never removed automatically.": "Notizen, Dokumente, Benutzer, Einstellungen und Schlüssel werden nie automatisch entfernt.",
  "Clear the {what}?": "{what} leeren?",
  "This deletes {what}": "Dies löscht {what}",
