  "Delete": "Löschen",
  "Cleared: {what}.": "Geleert: {what}.",
  "Save these limits?": "Diese Limits speichern?",
  "They remove now:": "Sie entfernen jetzt:",
  "This cannot be undone.": "Das kann nicht rückgängig gemacht werden.",
  "Save and remove": "Speichern und entfernen",
