  "Link is not set up yet.": "Link ist noch nicht eingerichtet.",
  "PLC-Ki Link is connected but sends no PLC values.": "PLC-Ki Link ist verbunden, sendet aber keine SPS-Werte.",
  "PLC-Ki Link is not connected. Start it on the laptop that reaches the PLC (Setup, Connections).": "PLC-Ki Link ist nicht verbunden. Starten Sie es auf dem Laptop, der die SPS erreicht (Einrichtung, Verbindungen).",
  "Not connected.": "Nicht verbunden.",
  "Not connected to the PLC.": "Nicht mit der SPS verbunden.",
  "The PLC connection closed during this read.": "Die SPS-Verbindung wurde während dieses Lesens geschlossen.",
  "The CPU did not say its mode.": "Die CPU hat ihren Betriebszustand nicht gemeldet.",
  "Live values for tags outside the machine model need a direct PLC connection.": "Livewerte für Variablen außerhalb des Maschinenmodells brauchen eine direkte SPS-Verbindung.",
  "Another change is still being written. Try again in a moment.": "Eine andere Änderung wird noch geschrieben. Versuchen Sie es gleich noch einmal.",
  "The TIA helper gave no input value.": "Der TIA-Helfer hat keinen Eingangswert geliefert.",
  "A test switch is on in the PLC. A fault may be caused on purpose, not by the machine.": "In der SPS ist ein Testschalter eingeschaltet. Eine Störung kann absichtlich ausgelöst sein, nicht von der Maschine.",
  "Ask is switched off for this PLC-Ki.": "Ki fragen ist für diese PLC-Ki ausgeschaltet.",
  "Ask needs a Claude key, and none is set yet.": "Ki fragen braucht einen Claude-Schlüssel, und es ist noch keiner eingetragen.",
  "Answered by the fallback model because the main model declined this question.": "Von dem Ersatzmodell beantwortet, weil das Hauptmodell diese Frage abgelehnt hat.",
  "The answer was cut off because it got too long. Ask for a shorter answer or a specific part.": "Die Antwort wurde abgeschnitten, weil sie zu lang wurde. Bitten Sie um eine kürzere Antwort oder einen bestimmten Teil.",
  "Recommended: good answers at a fair price.": "Empfohlen: gute Antworten zu einem fairen Preis.",
  "Faster, about half the price.": "Schneller, etwa der halbe Preis.",
  "The most capable, about twice the price.": "Am leistungsfähigsten, etwa der doppelte Preis.",
  "Production log: keep 7 to 3650 days.": "Produktionsprotokoll: 7 bis 3650 Tage aufbewahren.",
  "Machine events: keep 7 to 3650 days.": "Maschinenereignisse: 7 bis 3650 Tage aufbewahren.",
