  "Alarm recordings: keep 1 to 2000.": "Alarmaufzeichnungen: 1 bis 2000 aufbewahren.",
  "Alarm memory: keep 100 to 200000 occurrences.": "Alarmspeicher: 100 bis 200000 Ereignisse aufbewahren.",
  "Value history": "Werteverlauf",
  "Fast recording": "Schnellaufzeichnung",
  "Handover notes": "Übergabenotizen",
  "Hold list": "Halteliste",
  "Settings, logins and keys": "Einstellungen, Logins und Schlüssel",
  "Every value, for the charts and \"what happened before the alarm\".": "Jeder Wert, für die Diagramme und „Was geschah vor dem Alarm“.",
  "Every change the PLC sends, to cut the recording around an alarm.": "Jede Änderung, die die SPS sendet, um die Aufzeichnung um einen Alarm herum zuzuschneiden.",
  "The seconds around each alarm, value by value.": "Die Sekunden um jeden Alarm, Wert für Wert.",
  "What the machine did (running, idle, down), parts and cycles, for the shift, OEE and fault reports.": "Was die Maschine getan hat (läuft, bereit, Störung), Teile und Zyklen, für die Schicht-, OEE- und Störungsberichte.",
  "Every step change and every output switched on or off, for the timeline and the shift log.": "Jeder Schrittwechsel und jeder ein- oder ausgeschaltete Ausgang, für die Zeitleiste und das Schichtprotokoll.",
  "Alarms that came and went, halts, blocked devices, CPU mode, connection drops, values changed from PLC-Ki.": "Gekommene und gegangene Alarme, Halts, gesperrte Geräte, CPU-Betriebszustand, Verbindungsabbrüche, in PLC-Ki geänderte Werte.",
  "Numeric values for the trends: every read for the newest days, a minute at a time (lowest, highest, last) for older ones.": "Zahlenwerte für die Trends: jedes Lesen für die neuesten Tage, minutenweise (niedrigster, höchster, letzter) für ältere.",
  "Every value changed, held or refused from PLC-Ki, with who and why. Also every clear on this page.": "Jeder aus PLC-Ki geänderte, gehaltene oder abgelehnte Wert, mit Wer und Warum. Auch jedes Löschen auf dieser Seite.",
  "The note each shift leaves for the next one (Reports › Shift report).": "Die Notiz, die jede Schicht für die nächste hinterlässt (Berichte › Schichtbericht).",
