  "The safety program reads this value. PLC-Ki never changes it on a real machine. Click \"I understand\" to change it anyway.": "Das Sicherheitsprogramm liest diesen Wert. PLC-Ki ändert ihn an einer echten Maschine nie. Klicken Sie auf „Verstanden“, um es trotzdem zu ändern.",
  "The safety program reads this value. PLC-Ki never changes it on a real machine. Click \"I understand\" to hold it anyway.": "Das Sicherheitsprogramm liest diesen Wert. PLC-Ki ändert ihn an einer echten Maschine nie. Klicken Sie auf „Verstanden“, um es trotzdem zu halten.",
