  "it needs ON to go off and on again (OFF1 edge) after power-up, a fault reset or STO": "nach dem Einschalten, einer Störungsquittierung oder STO muss das EIN-Kommando aus- und wieder eingeschaltet werden (AUS1-Flanke)",
